def group_coverage(self, groups, from_on, to_on, absences=None, member_ids=None):
    # Read-only per-group absence preview over preview_absence_coverage:
    # the qualified and absent members per day are computed exactly as
    # there, but every group is judged on its own — a member enters one
    # group's qualified list as soon as that group is valid for them that
    # day, without needing the other groups to be valid, and the same
    # member may count in several groups at once. The headcount
    # requirement moves from the top level into each group. The groups and
    # absences exist only for this call: nothing is ever stored, and
    # enrollments, completion records and profiles are used as they are,
    # never reconstructed historically; the current date is never
    # consulted.
    if not isinstance(groups, list) or not groups:
        raise ValueError("groups must be a nonempty array")
    selected_groups = []
    seen_groups = set()
    seen_activities = set()
    for item in groups:
        if not isinstance(item, dict) or set(item) != {"group_id", "activity_ids", "valid_days", "minimum_count"}:
            raise ValueError("each group must contain only group_id, activity_ids, valid_days and minimum_count")
        group_id = text(item["group_id"], "group_id")
        if group_id in seen_groups:
            raise ValueError("group_ids must not contain duplicates")
        seen_groups.add(group_id)
        valid_days = positive(item["valid_days"], "valid_days")
        # The per-group headcount is a non-boolean positive integer; it may
        # exceed the number of selected members.
        minimum_count = positive(item["minimum_count"], "minimum_count")
        activity_ids = item["activity_ids"]
        if not isinstance(activity_ids, list) or not activity_ids:
            raise ValueError("activity_ids must be a nonempty array")
        group_activities = []
        for activity_id in activity_ids:
            activity_id = text(activity_id, "activity_id")
            # As in preview_absence_coverage, an activity belongs to
            # exactly one group and may not repeat inside it.
            if activity_id in seen_activities:
                raise ValueError("activity_ids must not repeat within or across groups")
            seen_activities.add(activity_id)
            group_activities.append(activity_id)
        selected_groups.append((group_id, group_activities, valid_days, minimum_count))
    from_on = day(from_on, "from_on")
    to_on = day(to_on, "to_on")
    if from_on > to_on:
        raise ValueError("from_on must be on or before to_on")
    # The absence list is required, exactly as in preview_absence_coverage:
    # null (or a missing argument) is rejected, an empty array is allowed.
    if absences is None or not isinstance(absences, list):
        raise ValueError("absences must be an array")
    absence_entries = []
    for item in absences:
        if not isinstance(item, dict) or set(item) != {"member_id", "from_on", "to_on"}:
            raise ValueError("each absence must contain only member_id, from_on and to_on")
        absence_member_id = text(item["member_id"], "member_id")
        absence_from = day(item["from_on"], "from_on")
        absence_to = day(item["to_on"], "to_on")
        # Whole-day closed intervals; a reversed range is rejected.
        if absence_from > absence_to:
            raise ValueError("from_on must be on or before to_on")
        absence_entries.append((absence_member_id, absence_from, absence_to))
    # member_ids follows preview_absence_coverage exactly: omitted or null
    # means every member, an empty array means no members at all.
    if member_ids is None:
        selected_member_ids = None
    elif not isinstance(member_ids, list):
        raise ValueError("member_ids must be an array or null")
    else:
        selected_member_ids = []
        seen_members = set()
        for member_id in member_ids:
            member_id = text(member_id, "member_id")
            if member_id in seen_members:
                raise ValueError("member_ids must not contain duplicates")
            seen_members.add(member_id)
            selected_member_ids.append(member_id)
    data = self._read()
    members = data.get("members", {})
    activities = data.get("activities", {})
    completions = data.get("completions", {})
    # Every reference is validated even when nobody is selected and every
    # absence falls outside the range.
    for _, activity_ids, _, _ in selected_groups:
        for activity_id in activity_ids:
            if activities.get(activity_id) is None:
                raise ValueError("unknown activity")
    if selected_member_ids is None:
        # Everyone, by ascending identifier.
        ordered_member_ids = sorted(members)
    else:
        for member_id in selected_member_ids:
            if member_id not in members:
                raise ValueError("unknown member")
        ordered_member_ids = selected_member_ids
    for absence_member_id, _, _ in absence_entries:
        if absence_member_id not in members:
            raise ValueError("unknown member")
    start = date.fromisoformat(from_on)
    end = date.fromisoformat(to_on)

    def valid_intervals(member_id, activity_ids, valid_days):
        # The eligible records are exactly preview_absence_coverage's,
        # which are exactly training_validity's: a stored completion only
        # exists for enrolled members, and a missing record is the same as
        # no record.
        records_by_date = {}
        for activity_id in activity_ids:
            activity = activities[activity_id]
            if member_id not in activity.get("participants", []):
                continue
            completed_on = completions.get(activity_id, {}).get(member_id)
            if completed_on is not None:
                records_by_date.setdefault(date.fromisoformat(completed_on), []).append(
                    (activity["on"], activity_id)
                )
        takeovers = sorted(records_by_date)
        intervals = []
        for index, completed in enumerate(takeovers):
            segment_end = takeovers[index + 1] - timedelta(days=1) if index + 1 < len(takeovers) else date.max
            # The expiry is the completion day plus valid_days calendar
            # days; the expiry day itself is expired. An expiry past
            # date.max is beyond every possible range end, so the record
            # stays valid through the range instead of raising.
            try:
                expires = completed + timedelta(days=valid_days)
            except OverflowError:
                expires = None
            valid_end = segment_end if expires is None else min(segment_end, expires - timedelta(days=1))
            frm, to = max(completed, start), min(valid_end, end)
            if frm <= to:
                intervals.append((frm, to))
        return intervals

    # Per member and group, the days on which that group alone is valid;
    # the groups are never intersected with each other.
    qualified = [
        [valid_intervals(member_id, activity_ids, valid_days) for _, activity_ids, valid_days, _ in selected_groups]
        for member_id in ordered_member_ids
    ]

    # Per selected member, the absence days inside the range, exactly as in
    # preview_absence_coverage: repeated, overlapping or adjacent requests
    # are a union of days and never deduct the member twice; absences of
    # members not selected and days outside the range never change the
    # counts.
    absent = {member_id: [] for member_id in ordered_member_ids}
    for absence_member_id, absence_from, absence_to in absence_entries:
        if absence_member_id not in absent:
            continue
        frm = max(date.fromisoformat(absence_from), start)
        to = min(date.fromisoformat(absence_to), end)
        if frm <= to:
            absent[absence_member_id].append((frm, to))

    # Sweep the range: any group's qualified set or the absent set can only
    # change where one of the intervals starts or ends, so the days between
    # consecutive edges share every set. Every edge lies inside the range,
    # so no date overflows.
    edges = set()
    for per_group in qualified:
        for intervals in per_group:
            for frm, to in intervals:
                if frm > start:
                    edges.add(frm)
                if to < end:
                    edges.add(to + timedelta(days=1))
    for intervals in absent.values():
        for frm, to in intervals:
            if frm > start:
                edges.add(frm)
            if to < end:
                edges.add(to + timedelta(days=1))
    boundaries = [start] + sorted(edges)
    periods = []
    for index, frm in enumerate(boundaries):
        to = boundaries[index + 1] - timedelta(days=1) if index + 1 < len(boundaries) else end
        key = tuple(
            (
                tuple(
                    member_id
                    for member_id, member_qualified in zip(ordered_member_ids, qualified)
                    if any(f <= frm <= t for f, t in member_qualified[group_index])
                ),
                tuple(
                    member_id
                    for member_id, member_qualified in zip(ordered_member_ids, qualified)
                    if any(f <= frm <= t for f, t in member_qualified[group_index])
                    and any(f <= frm <= t for f, t in absent[member_id])
                ),
            )
            for group_index in range(len(selected_groups))
        )
        if periods and periods[-1][2] == key:
            # Same qualified and absent members in every group on the
            # following days extend the open period instead of starting a
            # new one; a same-size swap of people still splits, and a mere
            # change of the underlying completion record never does.
            periods[-1][1] = to
        else:
            periods.append([frm, to, key])
    return {
        "from_on": from_on,
        "to_on": to_on,
        "periods": [
            {
                "from_on": frm.isoformat(),
                "to_on": to.isoformat(),
                "groups": [
                    {
                        "group_id": group_id,
                        "minimum_count": minimum_count,
                        "valid_member_ids": list(ids),
                        "valid_count": len(ids),
                        "absent_member_ids": list(away),
                        "available_member_ids": [member_id for member_id in ids if member_id not in away],
                        "available_count": len(ids) - len(away),
                        "shortage_count": max(0, minimum_count - (len(ids) - len(away))),
                    }
                    for (group_id, _, _, minimum_count), (ids, away) in zip(selected_groups, key)
                ],
                # Only a period where no group is short meets the
                # requirements.
                "meets_requirements": all(
                    len(ids) - len(away) >= minimum_count
                    for (_, _, _, minimum_count), (ids, away) in zip(selected_groups, key)
                ),
            }
            for frm, to, key in periods
        ],
    }

def absence_start_options(self, groups, from_on, to_on, minimum_count, absences=None, member_id=None, days=None, member_ids=None, avoid_pending_training=False):
    # Read-only start-date recommendation over preview_absence_coverage:
    # the qualified and absent members per day are computed exactly as
    # there, and on top of that one ephemeral leave of `days` consecutive
    # calendar days for one selected member is tried at every possible
    # start date. With avoid_pending_training, a start is additionally
    # rejected whenever the leave would cover a pending training of the
    # leave taker. The leave exists only for this call: nothing is ever
    # stored, and enrollments, completion records and profiles are used as
    # they are, never reconstructed historically; the current date is
    # never consulted.
    if not isinstance(groups, list) or not groups:
        raise ValueError("groups must be a nonempty array")
    selected_groups = []
    seen_groups = set()
    seen_activities = set()
    for item in groups:
        if not isinstance(item, dict) or set(item) != {"group_id", "activity_ids", "valid_days"}:
            raise ValueError("each group must contain only group_id, activity_ids and valid_days")
        group_id = text(item["group_id"], "group_id")
        if group_id in seen_groups:
            raise ValueError("group_ids must not contain duplicates")
        seen_groups.add(group_id)
        valid_days = positive(item["valid_days"], "valid_days")
        activity_ids = item["activity_ids"]
        if not isinstance(activity_ids, list) or not activity_ids:
            raise ValueError("activity_ids must be a nonempty array")
        group_activities = []
        for activity_id in activity_ids:
            activity_id = text(activity_id, "activity_id")
            # As in preview_absence_coverage, an activity belongs to
            # exactly one group and may not repeat inside it.
            if activity_id in seen_activities:
                raise ValueError("activity_ids must not repeat within or across groups")
            seen_activities.add(activity_id)
            group_activities.append(activity_id)
        selected_groups.append((group_id, group_activities, valid_days))
    from_on = day(from_on, "from_on")
    to_on = day(to_on, "to_on")
    if from_on > to_on:
        raise ValueError("from_on must be on or before to_on")
    minimum_count = positive(minimum_count, "minimum_count")
    # The absence list is required, exactly as in preview_absence_coverage:
    # null (or a missing argument) is rejected, an empty array is allowed.
    if absences is None or not isinstance(absences, list):
        raise ValueError("absences must be an array")
    absence_entries = []
    for item in absences:
        if not isinstance(item, dict) or set(item) != {"member_id", "from_on", "to_on"}:
            raise ValueError("each absence must contain only member_id, from_on and to_on")
        absence_member_id = text(item["member_id"], "member_id")
        absence_from = day(item["from_on"], "from_on")
        absence_to = day(item["to_on"], "to_on")
        # Whole-day closed intervals; a reversed range is rejected.
        if absence_from > absence_to:
            raise ValueError("from_on must be on or before to_on")
        absence_entries.append((absence_member_id, absence_from, absence_to))
    # The leave taker is required: trimmed and nonempty here, and checked
    # below to exist and to be one of the selected members.
    member_id = text(member_id, "member_id")
    # The leave length is a non-boolean positive integer of calendar days.
    days = positive(days, "days")
    # The pending-training filter is an optional strict boolean; null,
    # numbers and strings are rejected exactly like available_only.
    if type(avoid_pending_training) is not bool:
        raise ValueError("avoid_pending_training must be a boolean")
    # member_ids follows preview_absence_coverage exactly: omitted or null
    # means every member, an empty array means no members at all.
    if member_ids is None:
        selected_member_ids = None
    elif not isinstance(member_ids, list):
        raise ValueError("member_ids must be an array or null")
    else:
        selected_member_ids = []
        seen_members = set()
        for selected in member_ids:
            selected = text(selected, "member_id")
            if selected in seen_members:
                raise ValueError("member_ids must not contain duplicates")
            seen_members.add(selected)
            selected_member_ids.append(selected)
    data = self._read()
    members = data.get("members", {})
    activities = data.get("activities", {})
    completions = data.get("completions", {})
    # Every reference is validated even when no start date can fit.
    for _, activity_ids, _ in selected_groups:
        for activity_id in activity_ids:
            if activities.get(activity_id) is None:
                raise ValueError("unknown activity")
    if selected_member_ids is None:
        # Everyone, by ascending identifier.
        ordered_member_ids = sorted(members)
    else:
        for selected in selected_member_ids:
            if selected not in members:
                raise ValueError("unknown member")
        ordered_member_ids = selected_member_ids
    for absence_member_id, _, _ in absence_entries:
        if absence_member_id not in members:
            raise ValueError("unknown member")
    if member_id not in members:
        raise ValueError("unknown member")
    if member_id not in ordered_member_ids:
        raise ValueError("member_id must be one of the selected members")
    start = date.fromisoformat(from_on)
    end = date.fromisoformat(to_on)

    def valid_intervals(member, activity_ids, valid_days):
        # The eligible records are exactly preview_absence_coverage's,
        # which are exactly training_validity's: a stored completion only
        # exists for enrolled members, and a missing record is the same as
        # no record.
        records_by_date = {}
        for activity_id in activity_ids:
            activity = activities[activity_id]
            if member not in activity.get("participants", []):
                continue
            completed_on = completions.get(activity_id, {}).get(member)
            if completed_on is not None:
                records_by_date.setdefault(date.fromisoformat(completed_on), []).append(
                    (activity["on"], activity_id)
                )
        takeovers = sorted(records_by_date)
        intervals = []
        for index, completed in enumerate(takeovers):
            segment_end = takeovers[index + 1] - timedelta(days=1) if index + 1 < len(takeovers) else date.max
            # The expiry is the completion day plus valid_days calendar
            # days; the expiry day itself is expired. An expiry past
            # date.max is beyond every possible range end, so the record
            # stays valid through the range instead of raising.
            try:
                expires = completed + timedelta(days=valid_days)
            except OverflowError:
                expires = None
            valid_end = segment_end if expires is None else min(segment_end, expires - timedelta(days=1))
            frm, to = max(completed, start), min(valid_end, end)
            if frm <= to:
                intervals.append((frm, to))
        return intervals

    def intersect(first, second):
        # Both lists hold sorted, disjoint closed intervals; the result
        # keeps only the days covered by both.
        merged = []
        i = j = 0
        while i < len(first) and j < len(second):
            frm = max(first[i][0], second[j][0])
            to = min(first[i][1], second[j][1])
            if frm <= to:
                merged.append((frm, to))
            if first[i][1] < second[j][1]:
                i += 1
            else:
                j += 1
        return merged

    # Per member, the days on which every selected group is valid at once.
    qualified = []
    for member in ordered_member_ids:
        intervals = valid_intervals(member, selected_groups[0][1], selected_groups[0][2])
        for _, activity_ids, valid_days in selected_groups[1:]:
            if not intervals:
                break
            intervals = intersect(intervals, valid_intervals(member, activity_ids, valid_days))
        qualified.append(intervals)

    # Per selected member, the absence days inside the range, exactly as in
    # preview_absence_coverage: repeated, overlapping or adjacent requests
    # are a union of days and never deduct the member twice; absences of
    # members not selected and days outside the range never change the
    # counts.
    absent = {member: [] for member in ordered_member_ids}
    for absence_member_id, absence_from, absence_to in absence_entries:
        if absence_member_id not in absent:
            continue
        frm = max(date.fromisoformat(absence_from), start)
        to = min(date.fromisoformat(absence_to), end)
        if frm <= to:
            absent[absence_member_id].append((frm, to))

    # With avoid_pending_training, a day also breaks every candidate leave
    # covering it when the leave taker has a pending training that day.
    # Pending matches schedule exactly: every activity the member is
    # currently enrolled in, regardless of the queried groups, without an
    # own completion record. A record dated even beyond the query range
    # clears it; other members' enrollments and activities the member is
    # not enrolled in never block. Activities outside the range are
    # irrelevant because no candidate leave can cover them. Several
    # pending activities on one day block that day only once.
    pending_days = set()
    if avoid_pending_training:
        for activity in activities.values():
            if member_id not in activity.get("participants", []):
                continue
            if completions.get(activity["activity_id"], {}).get(member_id) is not None:
                continue
            on = date.fromisoformat(activity["on"])
            if start <= on <= end:
                pending_days.add(on)

    # Sweep the range exactly as in preview_absence_coverage: the
    # qualified set or the absent set can only change where one of the
    # intervals starts or ends, so the days between consecutive edges
    # share both sets. Pending training days add their own edges so each
    # is judged separately. Every edge lies inside the range, so no date
    # overflows.
    edges = set()
    for intervals in qualified:
        for frm, to in intervals:
            if frm > start:
                edges.add(frm)
            if to < end:
                edges.add(to + timedelta(days=1))
    for intervals in absent.values():
        for frm, to in intervals:
            if frm > start:
                edges.add(frm)
            if to < end:
                edges.add(to + timedelta(days=1))
    for on in pending_days:
        if on > start:
            edges.add(on)
        if on < end:
            edges.add(on + timedelta(days=1))
    boundaries = [start] + sorted(edges)
    # Maximal runs of days on which the candidate leave is infeasible:
    # either it would break the headcount, or the day holds a pending
    # training of the leave taker. For the headcount rule the leave taker
    # only deducts when they are qualified and not already absent that
    # day, and only the days inside the candidate leave are judged, so
    # gaps elsewhere never affect a candidate.
    bad = []
    for index, frm in enumerate(boundaries):
        to = boundaries[index + 1] - timedelta(days=1) if index + 1 < len(boundaries) else end
        available_ids = [
            member
            for member, intervals in zip(ordered_member_ids, qualified)
            if any(f <= frm <= t for f, t in intervals)
            and not any(f <= frm <= t for f, t in absent[member])
        ]
        # The leave taker only deducts when they are qualified and not
        # already absent that day; only the days inside the candidate
        # leave are judged, so gaps elsewhere never affect a candidate.
        # A pending training of the applicant blocks regardless of their
        # qualification or existing absence that day.
        available = len(available_ids) - (1 if member_id in available_ids else 0)
        if available < minimum_count or frm in pending_days:
            if bad and bad[-1][1] == frm - timedelta(days=1):
                bad[-1][1] = to
            else:
                bad.append([frm, to])
    windows = []
    # A leave longer than the query range can never fit; the start windows
    # are simply empty then. Otherwise the latest start still ends inside
    # the range, so no date arithmetic can overflow.
    if days <= (end - start).days + 1:
        last_start = end - timedelta(days=days - 1)
        # A start is feasible exactly when its whole leave avoids the bad
        # runs, so the feasible starts between two bad runs form one
        # maximal closed interval each; consecutive feasible starts are
        # merged into the longest interval even when the underlying
        # qualified roster changes inside it.
        cursor = start
        for bad_from, bad_to in bad:
            if (bad_from - cursor).days >= days:
                windows.append((cursor, bad_from - timedelta(days=days)))
            if bad_to == end:
                cursor = None
                break
            cursor = bad_to + timedelta(days=1)
        if cursor is not None and cursor <= last_start:
            windows.append((cursor, last_start))
    return {
        "from_on": from_on,
        "to_on": to_on,
        "minimum_count": minimum_count,
        "member_id": member_id,
        "days": days,
        "start_windows": [
            {"from_on": frm.isoformat(), "to_on": to.isoformat()}
            for frm, to in windows
        ],
    }

def group_absence_start_options(self, groups, from_on, to_on, absences=None, member_id=None, days=None, member_ids=None):
    # Read-only per-group start-date recommendation over group_coverage:
    # the qualified and absent members per day and the per-group
    # headcount requirements are computed exactly as there, and on top
    # of that one ephemeral leave of `days` consecutive calendar days for
    # one selected member is tried at every possible start date. Every
    # group is judged on its own: the leave taker only deducts from a
    # group on a day when that group alone is valid for them and they are
    # not already absent; the same member may keep counting in the other
    # groups. The groups, absences and leave exist only for this call:
    # nothing is ever stored, enrollments, completion records and
    # profiles are used as they are, never reconstructed historically,
    # and the current date is never consulted.
    if not isinstance(groups, list) or not groups:
        raise ValueError("groups must be a nonempty array")
    selected_groups = []
    seen_groups = set()
    seen_activities = set()
    for item in groups:
        if not isinstance(item, dict) or set(item) != {"group_id", "activity_ids", "valid_days", "minimum_count"}:
            raise ValueError("each group must contain only group_id, activity_ids, valid_days and minimum_count")
        group_id = text(item["group_id"], "group_id")
        if group_id in seen_groups:
            raise ValueError("group_ids must not contain duplicates")
        seen_groups.add(group_id)
        valid_days = positive(item["valid_days"], "valid_days")
        # The per-group headcount is a non-boolean positive integer; it may
        # exceed the number of selected members.
        minimum_count = positive(item["minimum_count"], "minimum_count")
        activity_ids = item["activity_ids"]
        if not isinstance(activity_ids, list) or not activity_ids:
            raise ValueError("activity_ids must be a nonempty array")
        group_activities = []
        for activity_id in activity_ids:
            activity_id = text(activity_id, "activity_id")
            # As in group_coverage, an activity belongs to exactly one
            # group and may not repeat inside it.
            if activity_id in seen_activities:
                raise ValueError("activity_ids must not repeat within or across groups")
            seen_activities.add(activity_id)
            group_activities.append(activity_id)
        selected_groups.append((group_id, group_activities, valid_days, minimum_count))
    from_on = day(from_on, "from_on")
    to_on = day(to_on, "to_on")
    if from_on > to_on:
        raise ValueError("from_on must be on or before to_on")
    # The absence list is required, exactly as in group_coverage: null (or
    # a missing argument) is rejected, an empty array is allowed.
    if absences is None or not isinstance(absences, list):
        raise ValueError("absences must be an array")
    absence_entries = []
    for item in absences:
        if not isinstance(item, dict) or set(item) != {"member_id", "from_on", "to_on"}:
            raise ValueError("each absence must contain only member_id, from_on and to_on")
        absence_member_id = text(item["member_id"], "member_id")
        absence_from = day(item["from_on"], "from_on")
        absence_to = day(item["to_on"], "to_on")
        # Whole-day closed intervals; a reversed range is rejected.
        if absence_from > absence_to:
            raise ValueError("from_on must be on or before to_on")
        absence_entries.append((absence_member_id, absence_from, absence_to))
