    # the groups are never intersected with each other.
    qualified = [
        [valid_intervals(member, activity_ids, valid_days) for _, activity_ids, valid_days, _ in selected_groups]
        for member in ordered_member_ids
    ]

    # Per selected member, the absence days inside the range, exactly as in
    # group_coverage: repeated, overlapping or adjacent requests are a
    # union of days and never deduct the member twice; absences of members
    # not selected and days outside the range never change the counts.
    absent = {member: [] for member in ordered_member_ids}
    for absence_member_id, absence_from, absence_to in absence_entries:
        if absence_member_id not in absent:
            continue
        frm = max(date.fromisoformat(absence_from), start)
        to = min(date.fromisoformat(absence_to), end)
        if frm <= to:
            absent[absence_member_id].append((frm, to))

    # Sweep the range exactly as in group_coverage: any group's qualified
    # set or the absent set can only change where one of the intervals
    # starts or ends, so the days between consecutive edges share every
    # set. Every edge lies inside the range, so no date overflows.
    edges = set()
    for per_group in qualified:
        for intervals in per_group:
            for frm, to in intervals:
                if frm > start:
                    edges.add(frm)
                if to < end:
                    edges.add(to + timedelta(days=1))
    for intervals in absent.values():
        for frm, to in intervals:
            if frm > start:
                edges.add(frm)
            if to < end:
                edges.add(to + timedelta(days=1))
    boundaries = [start] + sorted(edges)
    # Maximal runs of days on which the candidate leave is infeasible: at
    # least one group would drop below its own headcount. The groups are
    # judged independently, so one bad group spoils the day for the
    # candidate while a group the leave taker is not qualified for (or is
    # already absent from) does not deduct them. Only the days inside the
    # candidate leave are judged, so gaps elsewhere never matter.
    bad = []
    for index, frm in enumerate(boundaries):
        to = boundaries[index + 1] - timedelta(days=1) if index + 1 < len(boundaries) else end
        day_is_bad = False
        for group_index, (_, _, _, minimum_count) in enumerate(selected_groups):
            available_ids = [
                member
                for member, per_group in zip(ordered_member_ids, qualified)
                if any(f <= frm <= t for f, t in per_group[group_index])
                and not any(f <= frm <= t for f, t in absent[member])
            ]
            # The leave taker only deducts from this group when they are
            # qualified for it and not already absent that day; being
            # unqualified or already away costs the group nothing.
            available = len(available_ids) - (1 if member_id in available_ids else 0)
            if available < minimum_count:
                day_is_bad = True
                break
        if day_is_bad:
            if bad and bad[-1][1] == frm - timedelta(days=1):
                bad[-1][1] = to
            else:
                bad.append([frm, to])
    windows = []
    # A leave longer than the query range can never fit; the start windows
    # are simply empty then. Otherwise the latest start still ends inside
    # the range, so no date arithmetic can overflow.
    if days <= (end - start).days + 1:
        last_start = end - timedelta(days=days - 1)
        # A start is feasible exactly when its whole leave avoids the bad
        # runs, so the feasible starts between two bad runs form one
        # maximal closed interval each; consecutive feasible starts are
        # merged into the longest interval even when the underlying
        # qualified roster changes inside it.
        cursor = start
        for bad_from, bad_to in bad:
            if (bad_from - cursor).days >= days:
                windows.append((cursor, bad_from - timedelta(days=days)))
            if bad_to == end:
                cursor = None
                break
            cursor = bad_to + timedelta(days=1)
        if cursor is not None and cursor <= last_start:
            windows.append((cursor, last_start))
    return {
        "from_on": from_on,
        "to_on": to_on,
        "member_id": member_id,
        "days": days,
        "start_windows": [
            {"from_on": frm.isoformat(), "to_on": to.isoformat()}
            for frm, to in windows
        ],
    }

def export_schedule(self, from_on=None, to_on=None, status="all"):
    if from_on is not None:
        from_on = day(from_on, "from_on")
    if to_on is not None:
        to_on = day(to_on, "to_on")
    if from_on is not None and to_on is not None and from_on > to_on:
        raise ValueError("from_on must be on or before to_on")
    if status not in ("all", "pending", "completed"):
        raise ValueError("status must be one of all, pending, completed")
    data = self._read()
    members = data.get("members", {})
    activities = data.get("activities", {})
    completions = data.get("completions", {})
    # Conflicts come from each member's full current enrollment, ignoring
    # the date range and status filters, exactly like member_schedule:
    # a completed or filtered-out enrollment still counts, other members'
    # enrollments never do.
    enrolled_on = {}
    for activity_id, activity in activities.items():
        for member_id in activity.get("participants", []):
            enrolled_on.setdefault(member_id, {}).setdefault(activity.get("on"), set()).add(activity_id)
    rows = []
    for activity_id, activity in activities.items():
        on = activity["on"]
        if from_on is not None and on < from_on:
            continue
        if to_on is not None and on > to_on:
            continue
        done = completions.get(activity_id, {})
        for member_id in activity.get("participants", []):
            completed_on = done.get(member_id)
            current = "completed" if completed_on is not None else "pending"
            if status != "all" and current != status:
                continue
            conflicts = sorted(aid for aid in enrolled_on[member_id].get(on, ()) if aid != activity_id)
            rows.append([
                member_id,
                members[member_id]["name"],
                activity_id,
                activity["title"],
                on,
                current,
                completed_on if completed_on is not None else "",
                json.dumps(conflicts, ensure_ascii=False, separators=(",", ":")),
            ])
    rows.sort(key=lambda row: (row[4], row[2], row[0]))
    buffer = io.StringIO()
    # QUOTE_MINIMAL quotes exactly the cells containing a comma, a double
    # quote or a newline; inner quotes are doubled. CRLF line endings, no
    # BOM, so Chinese text and embedded newlines survive untouched.
    writer = csv.writer(buffer, lineterminator="\r\n")
    writer.writerow(["member_id", "name", "activity_id", "title", "on", "status", "completed_on", "conflict_activity_ids"])
    writer.writerows(rows)
    return {"csv": buffer.getvalue(), "row_count": len(rows)}

from pathlib import Path
import json
import os
import tempfile
from datetime import date

COLLECTIONS = ("members", "activities", "completions")

class JsonStore:
    def __init__(self, root):
        self.root = Path(root)
        self.path = self.root / "data.json"

    def _read(self):
        # A missing file is an empty history. Any other filesystem problem
        # (permissions, data.json being a directory, ...) stays an OSError.
        try:
            raw = self.path.read_bytes()
        except FileNotFoundError:
            return {}
        try:
            text = raw.decode("utf-8")
        except UnicodeDecodeError:
            raise ValueError("data.json must be a valid UTF-8 file")
        try:
            value = json.loads(text)
        except json.JSONDecodeError:
            raise ValueError("data.json must be valid JSON")
        if not isinstance(value, dict):
            raise ValueError("stored document must be an object")
        # The whole history is validated on every read, so a query can never
        # hide an unrelated broken record behind its filters.
        validate_document(value)
        return value

    def _write(self, value):
        # Validate before touching the filesystem: invalid data never creates
        # a missing directory or file and never replaces an existing file.
        validate_document(value)
        self.root.mkdir(parents=True, exist_ok=True)
        fd, name = tempfile.mkstemp(prefix=".data-", suffix=".json", dir=self.root)
        try:
            with os.fdopen(fd, "w", encoding="utf-8") as stream:
                json.dump(value, stream, ensure_ascii=False, sort_keys=True, indent=2)
                stream.write("\n")
            os.replace(name, self.path)
        finally:
            if os.path.exists(name):
                os.unlink(name)

def text(value, label):
    if not isinstance(value, str) or not value.strip():
        raise ValueError(label + " must be a nonempty string")
    return value.strip()

def identifier(value, label):
    # Stored keys and participant ids are matched exactly, never trimmed:
    # surrounding whitespace or an empty string are invalid on disk.
    if not isinstance(value, str) or not value or value != value.strip():
        raise ValueError(label + " must be a nonempty string without surrounding whitespace")
    return value

def positive(value, label):
    if type(value) is not int or value <= 0:
        raise ValueError(label + " must be a positive integer")
    return value

def day(value, label):
    # Only a real YYYY-MM-DD calendar date is accepted: no other types,
    # no surrounding whitespace, no relaxed parsing.
    if not isinstance(value, str) or len(value) != 10 or value[4] != "-" or value[7] != "-":
        raise ValueError(label + " must be a YYYY-MM-DD date string")
    try:
        parsed = date(int(value[0:4]), int(value[5:7]), int(value[8:10]))
    except (ValueError, OverflowError):
        raise ValueError(label + " must be a real YYYY-MM-DD date")
    if parsed.isoformat() != value:
        raise ValueError(label + " must be a real YYYY-MM-DD date")
    return parsed.isoformat()

def validate_document(data):
    # Business consistency check for a whole historical document. Missing
    # collections are empty; present ones must be JSON objects (null is not an
    # empty object). Extra fields on the document, members and activities are
    # allowed and left untouched by the caller.
    if not isinstance(data, dict):
        raise ValueError("stored document must be an object")
    for name in COLLECTIONS:
        if name in data and not isinstance(data[name], dict):
            raise ValueError(name + " must be an object")
    members = data.get("members", {})
    activities = data.get("activities", {})
    completions = data.get("completions", {})

    for key, member in members.items():
        identifier(key, "member key")
        if not isinstance(member, dict):
            raise ValueError("member entry must be an object")
        if not isinstance(member.get("member_id"), str) or member["member_id"] != key:
            raise ValueError("member_id must match the member object key")
        if not isinstance(member.get("name"), str) or not member["name"].strip():
            raise ValueError("member name must be a nonblank string")

    activity_dates = {}
    for key, activity in activities.items():
        identifier(key, "activity key")
        if not isinstance(activity, dict):
            raise ValueError("activity entry must be an object")
        if not isinstance(activity.get("activity_id"), str) or activity["activity_id"] != key:
            raise ValueError("activity_id must match the activity object key")
        if not isinstance(activity.get("title"), str) or not activity["title"].strip():
            raise ValueError("activity title must be a nonblank string")
        activity_dates[key] = day(activity.get("on"), "on")
        positive(activity.get("capacity"), "capacity")
        participants = activity.get("participants")
        if not isinstance(participants, list):
            raise ValueError("participants must be an array")
        seen = set()
        for member_id in participants:
            identifier(member_id, "participant id")
            if member_id in seen:
                raise ValueError("participants must not contain duplicate member ids")
            if member_id not in members:
                raise ValueError("participant references an unknown member")
            seen.add(member_id)
        if len(participants) > activity["capacity"]:
            raise ValueError("participant count must not exceed capacity")

    for activity_id, done in completions.items():
        identifier(activity_id, "completion activity key")
        if not isinstance(done, dict):
            raise ValueError("completion records must be an object")
        if activity_id not in activities:
            raise ValueError("completion references an unknown activity")
        enrolled = set(activities[activity_id]["participants"])
        for member_id, completed_on in done.items():
            identifier(member_id, "completion member id")
            if member_id not in enrolled:
                raise ValueError("completion references a member not enrolled in the activity")
            completed_on = day(completed_on, "completed_on")
            if date.fromisoformat(completed_on) < date.fromisoformat(activity_dates[activity_id]):
                raise ValueError("completed_on must be on or after the activity date")

